const __dirname = dirname(fileURLToPath(import.meta.url));
const OWN_VERSION = JSON.parse(readFileSync(resolve(__dirname, "../package.json"), "utf8")).version;
const PACKAGE_NAME = "@suncreation/opencode-toolsearch";
const LEGACY_PACKAGE_NAME = "@suncreation/opencode-claude-patch";
const LEGACY_PACKAGE_CLI = "opencode-claude-patch";
const DEFAULT_CONFIG_PATH = resolve(homedir(), ".config/opencode/opencode.json");
const DEFAULT_RUNTIME_PATH = resolve(homedir(), ".cache/opencode");
const DEFAULT_AUTH_PATH = resolve(homedir(), ".local/share/opencode/auth.json");
const PROVIDER_CONFIG_PATH = resolve(homedir(), ".config/opencode/provider-patch.json");
