const ANTHROPIC_CLIENT_ID = "9d1c250a-e61b-44d9-88ed-5944d1962f5e";
const ANTHROPIC_REDIRECT_URI = "https://console.anthropic.com/oauth/code/callback";
const ANTHROPIC_SCOPES = "org:create_api_key user:profile user:inference";
function generateCodeVerifier() {
    return randomBytes(32).toString("base64url");
}
function generateCodeChallenge(verifier) {
    return createHash("sha256").update(verifier).digest("base64url");
}
function buildAnthropicAuthorizationUrl(mode, verifier) {
    const url = new URL(`https://${mode === "console" ? "console.anthropic.com" : "claude.ai"}/oauth/authorize`);
    url.searchParams.set("code", "true");
    url.searchParams.set("client_id", ANTHROPIC_CLIENT_ID);
    url.searchParams.set("response_type", "code");
    url.searchParams.set("redirect_uri", ANTHROPIC_REDIRECT_URI);
    url.searchParams.set("scope", ANTHROPIC_SCOPES);
    url.searchParams.set("code_challenge", generateCodeChallenge(verifier));
    url.searchParams.set("code_challenge_method", "S256");
