async function openBrowser(url) {
    const platform = process.platform;
    let command = "xdg-open";
    if (platform === "darwin")
        command = "open";
    if (platform === "win32")
        command = "explorer";
    await new Promise((resolvePromise) => {
        try {
            const child = spawn(command, [url], { stdio: "ignore", detached: true });
            child.on("error", () => resolvePromise());
            child.unref();
            resolvePromise();
        }
        catch {
            resolvePromise();
