}
function printHelp() {
    process.stdout.write(`@suncreation/opencode-toolsearch v${OWN_VERSION}

Commands:
  install    Install plugin (default). Detects providers and shows selector.
  remove     Remove plugin from opencode.json.
  status     Show current installation status.
  login      Authenticate with Anthropic OAuth.
  logout     Remove Anthropic credentials.
  refresh    Force-refresh Anthropic access token.

Flags:
  --config PATH       Path to opencode.json (default: ~/.config/opencode/opencode.json)
  --runtime PATH      Path to runtime cache (default: ~/.cache/opencode)
  --auth-path PATH    Path to auth.json (default: ~/.local/share/opencode/auth.json)
  --version VERSION   Package version to install (default: current)
  --mode MODE         Login mode: "max" or "console" (default: max)
  --code CODE         Authorization code (skip prompt)
  --no-open           Don't open browser during login
  --reselect          Re-show provider selector even if providers already configured
