`);
}
function parseArgs(argv) {
    const result = {
        command: "install",
        config: DEFAULT_CONFIG_PATH,
        runtime: DEFAULT_RUNTIME_PATH,
        version: OWN_VERSION,
        authPath: DEFAULT_AUTH_PATH,
        mode: "max",
        code: null,
        open: true,
        reselect: false
    };
    for (let index = 0; index < argv.length; index += 1) {
        const arg = argv[index];
        if (arg === "-h" || arg === "--help") {
            result.command = "help";
            continue;
        }
        if (arg === "install" || arg === "remove" || arg === "status" || arg === "login" || arg === "logout" || arg === "refresh") {
            result.command = arg;
            continue;
        }
        if (arg === "--reselect") {
            result.reselect = true;
            continue;
        }
        if (arg === "--config" && argv[index + 1]) {
            result.config = resolve(argv[index + 1].replace(/^~(?=$|\/)/, homedir()));
            index += 1;
            continue;
        }
        if (arg === "--runtime" && argv[index + 1]) {
            result.runtime = resolve(argv[index + 1].replace(/^~(?=$|\/)/, homedir()));
            index += 1;
            continue;
        }
        if (arg === "--version" && argv[index + 1]) {
            result.version = argv[index + 1];
            index += 1;
            continue;
        }
        if (arg === "--auth-path" && argv[index + 1]) {
            result.authPath = resolve(argv[index + 1].replace(/^~(?=$|\/)/, homedir()));
            index += 1;
            continue;
        }
        if (arg === "--mode" && argv[index + 1]) {
            result.mode = argv[index + 1];
            index += 1;
            continue;
        }
        if (arg === "--code" && argv[index + 1]) {
            result.code = argv[index + 1];
            index += 1;
            continue;
        }
        if (arg === "--no-open") {
            result.open = false;
        }
