    return result;
}
async function readConfig(configPath) {
    try {
        const raw = await readFile(configPath, "utf8");
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === "object" ? parsed : {};
    }
    catch {
        return { $schema: "https://opencode.ai/config.json" };
    }
}
async function writeConfig(configPath, data) {
    await mkdir(dirname(configPath), { recursive: true });
    await writeFile(configPath, `${JSON.stringify(data, null, 2)}\n`, "utf8");
}
async function readAuthData(authPath) {
    try {
        const raw = await readFile(authPath, "utf8");
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === "object" ? parsed : {};
    }
    catch {
        return {};
    }
}
async function writeAuthData(authPath, data) {
    await mkdir(dirname(authPath), { recursive: true });
    await writeFile(authPath, `${JSON.stringify(data, null, 2)}\n`, "utf8");
}
async function readProviderConfig() {
    try {
        const raw = await readFile(PROVIDER_CONFIG_PATH, "utf8");
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === "object" ? parsed : {};
