    }
}
async function writeProviderConfig(data) {
    await mkdir(dirname(PROVIDER_CONFIG_PATH), { recursive: true });
    await writeFile(PROVIDER_CONFIG_PATH, `${JSON.stringify(data, null, 2)}\n`, "utf8");
}
async function runInstaller(command, args, runtimePath) {
    await new Promise((resolvePromise, reject) => {
        const child = spawn(command, args, {
            cwd: runtimePath,
            stdio: "inherit",
            env: process.env
        });
        child.on("error", reject);
        child.on("exit", (code) => {
            if (code === 0) {
                resolvePromise();
                return;
            }
            reject(new Error(`${command} exited with code ${code}`));
        });
    });
}
async function ensureRuntimePackage(runtimePath, version) {
    await mkdir(runtimePath, { recursive: true });
    try {
        await runInstaller("bun", ["add", `${PACKAGE_NAME}@${version}`], runtimePath);
        return;
    }
    catch (error) {
        if (error && typeof error === "object" && "code" in error && error.code === "ENOENT") {
            await runInstaller("npm", ["install", `${PACKAGE_NAME}@${version}`], runtimePath);
            return;
        }
        try {
            await runInstaller("npm", ["install", `${PACKAGE_NAME}@${version}`], runtimePath);
            return;
        }
        catch {
            throw error;
        }
    }
}
async function exchangeAnthropicCode(code, verifier) {
    const [authCode, state] = code.split("#");
    const response = await fetch("https://console.anthropic.com/v1/oauth/token", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
            code: authCode,
            state,
            grant_type: "authorization_code",
            client_id: ANTHROPIC_CLIENT_ID,
            redirect_uri: ANTHROPIC_REDIRECT_URI,
            code_verifier: verifier
        })
    });
    if (!response.ok) {
        let detail = `${response.status}`;
        try {
            const body = await response.json();
            if (body.error) {
                detail = `${response.status} ${body.error}`;
                if (body.error_description)
                    detail += `: ${body.error_description}`;
            }
        }
        catch (error) {
            void error;
        }
        throw new Error(`Anthropic token exchange failed: ${detail}`);
    }
    const json = await response.json();
    return {
        type: "oauth",
        refresh: json.refresh_token,
        access: json.access_token,
        expires: Date.now() + json.expires_in * 1000
