async function loginAnthropic(args) {
    const verifier = generateCodeVerifier();
    const url = buildAnthropicAuthorizationUrl(args.mode, verifier);
    process.stdout.write(`Open this URL to sign in to Anthropic:\n${url}\n`);
    if (args.open) {
        await openBrowser(url);
    }
    const code = args.code ?? await prompt("Paste the authorization code here: ");
    const credentials = await exchangeAnthropicCode(code, verifier);
    const authData = await readAuthData(args.authPath);
    authData.anthropic = credentials;
    await writeAuthData(args.authPath, authData);
    process.stdout.write(`Saved Anthropic OAuth credentials to ${args.authPath}\n`);
}
async function logoutAnthropic(args) {
    const authData = await readAuthData(args.authPath);
    delete authData.anthropic;
    await writeAuthData(args.authPath, authData);
    process.stdout.write(`Removed Anthropic credentials from ${args.authPath}\n`);
}
async function refreshAnthropic(args) {
    const token = await forceRefreshOAuthAccessToken("anthropic", { authPath: args.authPath });
    process.stdout.write(`Refreshed Anthropic access token: ${token.slice(0, 16)}...\n`);
}
async function readExistingProviders() {
    const data = await readProviderConfig();
    if (Array.isArray(data.providers) && data.providers.length > 0 && data.providers.every((p) => typeof p === "string")) {
        return data.providers;
    }
    return [];
}
async function printStatus(args, config) {
    const plugin = Array.isArray(config.plugin) ? config.plugin : [];
    const authData = await readAuthData(args.authPath);
    const anthropic = authData.anthropic && typeof authData.anthropic === "object" ? authData.anthropic : null;
    const expires = anthropic && typeof anthropic.expires === "number" ? anthropic.expires : null;
    const expired = typeof expires === "number" ? expires <= Date.now() : null;
    const configuredProviders = await readExistingProviders();
    process.stdout.write(JSON.stringify({
        config: args.config,
        providerConfigPath: PROVIDER_CONFIG_PATH,
        authPath: args.authPath,
        pluginInstalled: plugin.some((entry) => isThisPlugin(entry)),
        legacyPackageFound: hasLegacyPlugin(config),
        providers: configuredProviders.length > 0 ? configuredProviders : undefined,
        anthropic: anthropic ? {
            type: anthropic.type,
            hasAccess: typeof anthropic.access === "string" && anthropic.access.length > 0,
            hasRefresh: typeof anthropic.refresh === "string" && anthropic.refresh.length > 0,
            expires,
            expired
