        plugin
    }, null, 2) + "\n");
}
// Strip a trailing @version from a (possibly scoped) plugin entry.
// "@suncreation/opencode-toolsearch@0.3.2" -> "@suncreation/opencode-toolsearch"
// "@suncreation/opencode-toolsearch"       -> "@suncreation/opencode-toolsearch"
function stripPluginVersion(entry) {
    const at = entry.lastIndexOf("@");
    return at > 0 ? entry.slice(0, at) : entry;
}
function isThisPlugin(entry) {
    return typeof entry === "string" && stripPluginVersion(entry) === PACKAGE_NAME;
}
// Pin the plugin entry to an explicit version. opencode installs each plugin
// into an isolated dir named `<module>@<spec>` and locks the resolved version
// there; a bare `@suncreation/opencode-toolsearch` resolves to `@latest` once
// and never refreshes, so a stale build keeps loading. Writing
