    filtered.push(pinned);
    next.plugin = filtered;
    return next;
}
function removePlugin(config) {
    const next = { ...config };
    const plugin = Array.isArray(next.plugin) ? next.plugin.filter((entry) => !isThisPlugin(entry)) : [];
    next.plugin = plugin;
    return next;
}
function hasLegacyPlugin(config) {
    const plugin = Array.isArray(config.plugin) ? config.plugin : [];
    return plugin.some((entry) => {
        if (typeof entry === "string")
            return entry === LEGACY_PACKAGE_NAME;
        if (entry !== null && typeof entry === "object") {
            const obj = entry;
            return obj.name === LEGACY_PACKAGE_NAME;
        }
        return false;
    });
}
function removeLegacyPlugin(config) {
    const next = { ...config };
    const plugin = Array.isArray(next.plugin)
        ? next.plugin.filter((entry) => {
            if (typeof entry === "string")
                return entry !== LEGACY_PACKAGE_NAME;
            if (entry !== null && typeof entry === "object") {
                return entry.name !== LEGACY_PACKAGE_NAME;
            }
            return true;
        })
        : [];
    next.plugin = plugin;
    return next;
}
function extractLegacyProviders(config) {
    const plugin = Array.isArray(config.plugin) ? config.plugin : [];
    for (const entry of plugin) {
        if (entry !== null && typeof entry === "object") {
            const obj = entry;
            if (obj.name === LEGACY_PACKAGE_NAME && Array.isArray(obj.providers)) {
                return obj.providers.filter((p) => typeof p === "string");
            }
