    return [];
}
async function removeLegacyRuntimePackage(runtimePath) {
    const legacyDir = resolve(runtimePath, "node_modules", LEGACY_PACKAGE_NAME);
    const { rm } = await import("node:fs/promises");
    await rm(legacyDir, { recursive: true, force: true }).catch(() => { });
}
async function removeLegacyBuiltinSkill() {
    const { rm } = await import("node:fs/promises");
    await rm(LEGACY_BUILTIN_SKILL_DIR, { recursive: true, force: true }).catch(() => { });
