async function migrateLegacyInstall(config, configPath, runtimePath) {
    if (!hasLegacyPlugin(config)) {
        return [];
    }
    const legacyProviders = extractLegacyProviders(config);
    process.stdout.write(`Found legacy ${LEGACY_PACKAGE_NAME} — migrating...\n`);
    const nextConfig = removeLegacyPlugin(config);
    await writeConfig(configPath, nextConfig);
    process.stdout.write(`  Removed ${LEGACY_PACKAGE_NAME} from opencode.json plugin list\n`);
    await removeLegacyRuntimePackage(runtimePath);
    process.stdout.write(`  Removed legacy runtime package from ${runtimePath}\n`);
