    const detectedById = new Map(detected.map((p) => [p.id, p]));
    process.stdout.write("\nDetected providers from your opencode.json:\n\n");
    for (const provider of detected) {
        process.stdout.write(`  ${provider.id.padEnd(20)} ${provider.label} *\n`);
