    process.stdout.write("\n  * = detected in your config\n\n");
    const defaultSelection = detectedIds.join(",");
    process.stdout.write(`Select providers to patch (comma-separated, Enter for default: ${defaultSelection}):\n> `);
    const answer = await prompt("");
    const selected = answer.length > 0
        ? answer.split(",").map((s) => s.trim().toLowerCase()).filter((s) => s.length > 0)
