        printHelp();
        return;
    }
    if (args.command === "status") {
        await printStatus(args, config);
        return;
    }
    if (args.command === "login") {
        await loginAnthropic(args);
        return;
    }
    if (args.command === "logout") {
        await logoutAnthropic(args);
        return;
    }
    if (args.command === "refresh") {
        await refreshAnthropic(args);
        return;
    }
    if (args.command === "install") {
        const migratedProviders = await migrateLegacyInstall(config, args.config, args.runtime);
        await ensureRuntimePackage(args.runtime, args.version);
        const existingProviders = args.reselect ? [] : await readExistingProviders();
        const providers = existingProviders.length > 0
            ? existingProviders
            : migratedProviders.length > 0
                ? migratedProviders
                : await selectProviders(config);
        const nextConfig = ensurePlugin(config, args.version);
        await writeConfig(args.config, nextConfig);
        await writeProviderConfig({ providers });
        const generated = await syncGeneratedMcpToolsearch(args.runtime, args.config);
        process.stdout.write(`Generated MCP toolsearch skill in ${generated.skillDir}\n`);
        process.stdout.write(`Installed ${PACKAGE_NAME} in ${args.config} (providers: ${providers.join(", ")})\n`);
        process.stdout.write(`Provider config saved to ${PROVIDER_CONFIG_PATH}\n`);
        return;
    }
    const nextConfig = args.command === "remove" ? removePlugin(config) : ensurePlugin(config, args.version);
    await writeConfig(args.config, nextConfig);
    process.stdout.write(`${args.command === "remove" ? "Removed" : "Installed"} ${PACKAGE_NAME} in ${args.config}\n`);
